const rows = $input.all().map(r => r.json).filter(r => r.customer_id && r.status === 'active');
const today = new Date();
today.setHours(0,0,0,0);

const atRisk = [];

for (const row of rows) {
  const signals = [];
  let riskScore = 0;

  const lastLogin = row.last_login_date ? new Date(row.last_login_date) : null;
  const daysSinceLogin = lastLogin ? Math.floor((today - lastLogin) / 86400000) : 999;

  const lastPayment = row.last_payment_date ? new Date(row.last_payment_date) : null;
  const nextRenewal = row.next_renewal_date ? new Date(row.next_renewal_date) : null;
  const daysToRenewal = nextRenewal ? Math.floor((nextRenewal - today) / 86400000) : null;

  const usageScore = parseFloat(row.weekly_usage_score) || 0;
  const supportTickets30d = parseInt(row.support_tickets_30d) || 0;
  const paymentFailures = parseInt(row.payment_failures_90d) || 0;
  const npsScore = row.nps_score !== '' && row.nps_score !== undefined ? parseFloat(row.nps_score) : null;
  const planDowngraded = row.plan_downgraded === 'TRUE' || row.plan_downgraded === true;
  const cancelAttempt = row.cancel_attempt === 'TRUE' || row.cancel_attempt === true;

  // Score signals
  if (daysSinceLogin > 30) { signals.push(`no login in ${daysSinceLogin} days`); riskScore += 25; }
  else if (daysSinceLogin > 14) { signals.push(`login gap: ${daysSinceLogin} days`); riskScore += 10; }

  if (usageScore < 20) { signals.push(`low usage score: ${usageScore}`); riskScore += 20; }
  else if (usageScore < 40) { signals.push(`declining usage: ${usageScore}`); riskScore += 10; }

  if (paymentFailures > 0) { signals.push(`${paymentFailures} payment failure(s)`); riskScore += paymentFailures >= 2 ? 30 : 15; }

  if (supportTickets30d >= 3) { signals.push(`${supportTickets30d} support tickets in 30d`); riskScore += 15; }

  if (npsScore !== null && npsScore <= 6) { signals.push(`NPS detractor: ${npsScore}`); riskScore += 20; }
  else if (npsScore !== null && npsScore <= 7) { signals.push(`NPS passive: ${npsScore}`); riskScore += 8; }

  if (planDowngraded) { signals.push('plan downgraded'); riskScore += 25; }
  if (cancelAttempt) { signals.push('cancel attempt logged'); riskScore += 40; }

  if (daysToRenewal !== null && daysToRenewal <= 14 && riskScore > 20) {
    signals.push(`renewal in ${daysToRenewal} days`);
    riskScore += 10;
  }

  if (riskScore < 20) continue;

  const riskLevel = riskScore >= 60 ? 'high' : riskScore >= 35 ? 'medium' : 'low';

  atRisk.push({
    customerId: row.customer_id,
    customerName: row.customer_name || 'Unknown',
    customerEmail: row.customer_email || '',
    plan: row.plan || '',
    mrr: parseFloat(row.mrr) || 0,
    currency: row.currency || 'USD',
    riskScore,
    riskLevel,
    signals,
    daysSinceLogin,
    usageScore,
    daysToRenewal,
    csm: row.csm || '',
    notes: row.notes || ''
  });
}

atRisk.sort((a, b) => b.riskScore - a.riskScore);

const totalMrrAtRisk = atRisk.reduce((s, c) => s + c.mrr, 0);
const highRisk = atRisk.filter(c => c.riskLevel === 'high');
const medRisk = atRisk.filter(c => c.riskLevel === 'medium');

return [{
  json: {
    atRisk,
    highRisk,
    medRisk,
    totalAtRisk: atRisk.length,
    totalMrrAtRisk: parseFloat(totalMrrAtRisk.toFixed(2)),
    totalScanned: rows.length,
    scanDate: today.toISOString().split('T')[0]
  }
}];

