const body = $input.first().json.body || {};
const rows = $('Load Subscribers').all().map(r => r.json).filter(r => r.customer_id);
const targetId = body.customer_id || '';
const found = rows.filter(r => !targetId || r.customer_id === targetId);
return found.map(r => ({ json: r }));
